?><!doctype html><html><head><meta charset="utf-8"><style>@page{size:A4;margin:0}*{box-sizing:border-box;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}body{margin:0;font-family:Arial;color:#073b25}.bar{padding:10px;text-align:center}.sheet{width:210mm;height:297mm;position:relative;margin:auto;overflow:hidden}.bg{position:absolute;inset:0;width:100%;height:100%;object-fit:fill;z-index:-1}.brand{position:absolute;top:6%;left:8%;right:8%;padding:5mm 7mm;background:rgba(255,255,255,.72);border-radius:5mm;display:flex;align-items:center;gap:5mm}.brand img{width:25mm}.brand b{font:700 19mm Georgia}.brand span{display:block;font-size:4mm;letter-spacing:1mm}.hero{position:absolute;top:43%;left:33%;right:7%;min-height:18%;padding:5mm 8mm;background:rgba(0,66,38,.78);border-radius:4mm;text-align:center;color:white}.hero h1{font:700 17mm Georgia;margin:0}.hero .title{font-size:5mm;font-weight:700;line-height:1.35;margin:2mm}.hero .text{font-size:3.7mm;line-height:1.35}.panel{position:absolute;top:62%;left:7%;right:7%;height:14%;display:grid;grid-template-columns:42% 31% 27%;align-items:center}.value{text-align:center}.value small,.dates small{display:block;font-size:3.2mm;letter-spacing:.8mm}.value strong{font:700 19mm Georgia}.code{font-size:3mm;font-weight:bold}.dates{border-left:1px solid #789;padding-left:5mm}.dates b{font:700 5mm Georgia}.qr{text-align:center;font-size:3mm}.qr img{width:23mm;height:23mm}.terms{position:absolute;top:80%;left:8%;right:37%;font-size:3mm;line-height:1.35}.terms h2{font-size:4mm;letter-spacing:1mm;margin:0 0 2mm}.scope{position:absolute;top:76.5%;left:8%;right:8%;text-align:center;font-size:3mm;font-weight:bold}@media print{.bar{display:none}.sheet{margin:0}}</style></head><body><div class="bar"><button onclick="window.print()">Print / Save as PDF</button> Enable “Background graphics” in the print dialog if required.</div><main class="sheet"><img class="bg" src="/filestore/images/coupons/ildra-voucher-background-v1.png"><div class="brand"><img src="/filestore/images/logos/ildra-logo.png"><div><b>ILDRA</b><span>IRISH LONG DISTANCE RIDING ASSOCIATION</span></div></div><section class="hero"><h1>VOUCHER</h1><div class="title"><?php echo h((string)($c['title']?:'A special gift from ILDRA'));?></div><?php if($c['message_html']):?><div class="text"><?php echo strip_tags((string)$c['message_html']);?></div><?php endif;?></section><div class="panel"><div class="value"><small>VOUCHER VALUE</small><strong><?php echo h(format_price($c['amount']));?></strong><div class="code"><?php echo h($c['code']);?></div></div><div class="dates"><small>VALID FROM</small><b><?php echo h(format_display_date($c['valid_from']));?></b><small>VALID TO</small><b><?php echo h(format_display_date($c['valid_until']));?></b></div><div class="qr"><?php if($qr):?><img src="<?php echo h($qr);?>"><?php endif;?><div>Scan to apply</div></div></div><div class="scope">Use: <?php echo h($c['event_title']?:'Eligible ILDRA entries and event-related purchases');?></div><section class="terms"><h2>TERMS &amp; CONDITIONS</h2><?php echo nl2br(h($terms));?></section></main></body></html>
